using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "MinimumSoulHeatCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/MinimumSoulHeatCustomDescription", order = 0)]
public class MinimumSoulHeatCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		MinimumSoulHeatAction obj = battleAction as MinimumSoulHeatAction;
		string minimumSoulHeatLocalized = obj.GetMinimumSoulHeatLocalized(obj.MinSoulHeatToUse);
		string text = "";
		text = GetRawLocalizedDescription(battleAction);
		Smart.Format(text, amountModified);
		string text2 = minimumSoulHeatLocalized + "\n" + text;
		if (obj.ResetSoulHeatAfterUse)
		{
			text2 = text2 + "\n" + base.localizationManager.GetLocalizedResetSoulHeat();
		}
		return text2;
	}
}
